import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import Bookmark01Icon from "@hugeicons/core-free-icons/Bookmark01Icon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleDemo() {
  return (
    <Toggle
      aria-label="Toggle bookmark"
      size="sm"
      variant="outline"
      className="data-[state=on]:bg-transparent data-[state=on]:*:[svg]:fill-info data-[state=on]:*:[svg]:stroke-info"
    >
      <HugeiconsIcon icon={Bookmark01Icon} />
      Bookmark
    </Toggle>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import UnderlineIcon from "@hugeicons/core-free-icons/UnderlineIcon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleDisabled() {
  return (
    <Toggle aria-label="Toggle italic" disabled>
      <HugeiconsIcon icon={UnderlineIcon} className="h-4 w-4" />
    </Toggle>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import ItalicIcon from "@hugeicons/core-free-icons/ItalicIcon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleOutline() {
  return (
    <Toggle variant="outline" aria-label="Toggle italic">
      <HugeiconsIcon icon={ItalicIcon} />
    </Toggle>
  );
}

import { Toggle } from "@/registry/erbium/ui/toggle";

export function ToggleSizes() {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <Toggle variant="outline" aria-label="Toggle small" size="sm">
        Small
      </Toggle>
      <Toggle variant="outline" aria-label="Toggle default" size="default">
        Default
      </Toggle>
      <Toggle variant="outline" aria-label="Toggle large" size="lg">
        Large
      </Toggle>
    </div>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
